    if closest_shirt.upper < closest_man.lower or closest_shirt.lower > closest_man.upper:
        return closest_man

    return closest_man.crop(max(closest_man.left, closest_shirt.left), max(closest_man.lower, closest_shirt.lower), min(closest_man.right, closest_shirt.right), min(closest_man.upper, closest_shirt.upper))

